module dram_cell(  
    input wire clk,  
    input wire write_enable,  
    input wire [7:0] data_in,  
    output reg [7:0] data_out  
);  
    reg [7:0] memory;  

    always @(posedge clk) begin  
        if (write_enable) begin  
            memory <= data_in;  
        end  
    end  

    always @(posedge clk) begin  
        data_out <= memory;  
    end  
endmodule

