module mux_4to1_with_forwarding(  
    input [7:0] in0,  
    input [7:0] in1,  
    input [7:0] in2,  
    input [7:0] in3,  
    input [1:0] sel,  
    input enable,  
    output reg [7:0] out  
);  
    always @(*) begin  
        if (enable) begin  
